 const [weeklyDraft,setWeeklyDraft]=useState(()=>{try{return typeof localStorage!=='undefined'?localStorage.getItem('tch-weekly-draft')||'':'';}catch{return '';}});
 useEffect(()=>{try{if(typeof localStorage!=='undefined')localStorage.setItem('tch-weekly-draft',weeklyDraft);}catch{}},[weeklyDraft]);
 useEffect(()=>{fetch('https://raw.githubusercontent.com/andrew6414/TreasureCoastHappenings/main/content/weekly-update.md').then(r=>r.ok?r.text():Promise.reject()).then(t=>setPublished(t.replace(/^#\s*/, '').replace(/\n---[\s\S]*$/, '').trim())).catch(()=>{});},[]);
 const [detail,setDetail]=useState(null);
